        "dumpint",
        "resultserver",
    ]

    def invoke(self, action, buf):
        if action not in self.actions:
            raise RuntimeError("Invalid ioctl action: %s" % action)

        return Ioctl.invoke(
            self, CTL_CODE_BASE + self.actions.index(action) * 4, buf,
        )

