READ_SIZE_BYTES = 1024*1024

# Adapters for different lzma bindings.
if hasattr(lzma, 'FORMAT_ALONE'):
    def _get_lzma_options(format, preset=None):
        kwargs = {'format':
                    {'alone': lzma.FORMAT_ALONE,
